package store_test

import (
	"flag"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/zarnautovic/tdeemon/internal/store/storetest"
)

var update = flag.Bool("update", false, "rewrite testdata/schema.sql from the migrations")

const schemaHeader = `-- The schema the migrations in migrations/ produce. Generated by
-- TestSchema; do not edit. Refresh it after adding a migration:
--   go test ./internal/store -run TestSchema -update

`

// TestSchema keeps testdata/schema.sql equal to the schema a fresh
// database gets, so a pull request that adds a migration also shows the
// full resulting schema.
func TestSchema(t *testing.T) {
	t.Parallel()

	db := storetest.Open(t)
	rows, err := db.Read().QueryContext(t.Context(), `
		SELECT sql FROM sqlite_schema
		WHERE sql IS NOT NULL AND name NOT LIKE 'sqlite_%'
		ORDER BY tbl_name,
			CASE type WHEN 'table' THEN 0 WHEN 'index' THEN 1 WHEN 'trigger' THEN 2 ELSE 3 END,
			name`)
	if err != nil {
		t.Fatalf("read schema: %v", err)
	}
	defer func() { _ = rows.Close() }()

	var b strings.Builder
	b.WriteString(schemaHeader)
	for rows.Next() {
		var stmt string
		if err := rows.Scan(&stmt); err != nil {
			t.Fatalf("scan: %v", err)
		}
		b.WriteString(stmt)
		b.WriteString(";\n\n")
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("rows: %v", err)
	}
	got := strings.TrimSuffix(b.String(), "\n")

	path := filepath.Join("testdata", "schema.sql")
	if *update {
		if err := os.WriteFile(path, []byte(got), 0o600); err != nil {
			t.Fatalf("write %s: %v", path, err)
		}
		return
	}
	want, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v (create it with -update)", path, err)
	}
	if string(want) != got {
		t.Errorf("%s is stale; refresh it with: go test ./internal/store -run TestSchema -update\n\ngot:\n%s", path, got)
	}
}
